64	  if (isdigit(LastChar) || LastChar == '.') { // Number: [0-9.]+
65	    std::string NumStr;
66	    do {
67	      NumStr += LastChar;
68	      LastChar = getchar();
69	    } while (isdigit(LastChar) || LastChar == '.');
