71	    NumVal = strtod(NumStr.c_str(), nullptr);
72	    return tok_number;
73	  }
74	
75	  if (LastChar == '#') {
76	    // Comment until end of line.
77	    do
78	      LastChar = getchar();
79	    while (LastChar != EOF && LastChar != '\n' && LastChar != '\r');
80	
81	    if (LastChar != EOF)
