334	/// expression
335	///   ::= primary binoprhs
336	///
337	static std::unique_ptr<ExprAST> ParseExpression() {
338	  auto LHS = ParsePrimary();
339	  if (!LHS)
340	    return nullptr;
341	
342	  return ParseBinOpRHS(0, std::move(LHS));
343	}
