483	Function *FunctionAST::codegen() {
484	  // First, check for an existing function from a previous 'extern' declaration.
485	  Function *TheFunction = TheModule->getFunction(Proto->getName());
486	
487	  if (!TheFunction)
488	    TheFunction = Proto->codegen();
489	
490	  if (!TheFunction)
491	    return nullptr;
492	
493	  if (!TheFunction->empty())
494	    return (Function *)LogErrorV("Function cannot be redefined.");
495	
496	  // Create a new basic block to start insertion into.
497	  BasicBlock *BB = BasicBlock::Create(*TheContext, "entry", TheFunction);
498	  Builder->SetInsertPoint(BB);
499	
500	  // Record the function arguments in the NamedValues map.
501	  NamedValues.clear();
502	  for (auto &Arg : TheFunction->args())
503	    NamedValues[std::string(Arg.getName())] = &Arg;
504	
505	  if (Value *RetVal = Body->codegen()) {
506	    // Finish off the function.
507	    Builder->CreateRet(RetVal);
508	
509	    // Validate the generated code, checking for consistency.
510	    verifyFunction(*TheFunction);
511	
512	    return TheFunction;
513	  }
514	
515	  // Error reading body, remove function.
516	  TheFunction->eraseFromParent();
517	  return nullptr;
518	}
